// Ikon aplikasi (PWA). Disajikan sebagai gambar PNG dari fungsi ini supaya cukup ditempel lewat Update App.
// Pemakaian: /api/icon?s=192  |  512  |  maskable  |  180
const ICONS = {
  "192": "",
  "512": "",
  "maskable": "",
  "180": "",
};

export async function onRequestGet({ request }) {
  const b64 = ICONS[new URL(request.url).searchParams.get("s") || "512"];
  if (!b64) return new Response("Not found", { status: 404 });
  const bin = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  return new Response(bin, {
    headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" }
  });
}